/*
 * HG native NCLR palette adapter.
 *
 * Original DS PLTT payload:
 *   +0  u32 format
 *   +4  u32 extended-palette flag
 *   +8  u32 raw-data size
 *   +12 u32 raw-data relative offset
 *
 * Keep the original resource allocation and bytes intact.
 */
static BOOL HG_DecodeNativePaletteForCopy(
    void *resource,
    u32 sourceOffset,
    u32 requestedSize,
    NNSG2dPaletteData *native)
{
    u8 *block;
    const u8 *payload;
    u32 blockSize;
    u32 rawSize;
    u32 rawOffset;
    u32 payloadSize;

    if (resource == NULL || native == NULL)
        return FALSE;

    block = NNS_G2dFindBinaryBlock(resource, (u32)'PLTT');
    if (block == NULL)
        return FALSE;

    memcpy(&blockSize, block + 4, sizeof(blockSize));
    if (blockSize < 24)
        return FALSE;

    payload = block + 8;
    payloadSize = blockSize - 8;

    memcpy(&rawSize, payload + 8, sizeof(rawSize));
    memcpy(&rawOffset, payload + 12, sizeof(rawOffset));

    if (rawOffset < 16 || rawOffset > payloadSize)
        return FALSE;

    if (rawSize > payloadSize - rawOffset)
        return FALSE;

    if (sourceOffset > rawSize)
        return FALSE;

    if (requestedSize != 0 &&
        requestedSize > rawSize - sourceOffset)
        return FALSE;

    memset(native, 0, sizeof(*native));
    native->szByte = rawSize;
    native->pRawData = (void *)(payload + rawOffset);

    return TRUE;
}
#endif

