/*
 * Native NCGR representation.
 *
 * The original binary CHAR payload remains 24 bytes:
 *
 * +0  u16 H
 * +2  u16 W
 * +4  u32 pixelFmt
 * +8  u32 mapingType
 * +12 u32 characterFmt
 * +16 u32 szByte
 * +20 u32 pRawData relative offset
 *
 * The native structure has an 8-byte data pointer.
 * Its lifetime follows CharResExtraData automatically.
 */
typedef struct HGNativeCharResExtra {
    struct CharResExtraData base;
    NNSG2dCharacterData native;
} HGNativeCharResExtra;

_Static_assert(
    offsetof(HGNativeCharResExtra, base) == 0,
    "character resource metadata prefix"
);
_Static_assert(
    sizeof(NNSG2dCharacterData) == 32,
    "native NCGR structure layout"
);
_Static_assert(
    offsetof(NNSG2dCharacterData, pRawData) == 24,
    "native NCGR pointer offset"
);

static BOOL HGDecodeNativeCharacter(
    void *resource,
    NNSG2dCharacterData *native)
{
    u8 *block;
    const u8 *p;
    u32 blockSize;
    u32 payloadSize;
    u32 pixelFmt;
    u32 mapping;
    u32 characterFmt;
    u32 dataSize;
    u32 dataOffset;
    u16 h, w;

    if (!resource || !native)
        return FALSE;

    block = NNS_G2dFindBinaryBlock(resource, (u32)'CHAR');
    if (!block)
        return FALSE;

    memcpy(&blockSize, block + 4, 4);
    if (blockSize < 32)
        return FALSE;

    p = block + 8;
    payloadSize = blockSize - 8;

    memcpy(&h, p, 2);
    memcpy(&w, p + 2, 2);
    memcpy(&pixelFmt, p + 4, 4);
    memcpy(&mapping, p + 8, 4);
    memcpy(&characterFmt, p + 12, 4);
    memcpy(&dataSize, p + 16, 4);
    memcpy(&dataOffset, p + 20, 4);

    if (dataOffset < 24 || dataOffset > payloadSize)
        return FALSE;

    if (dataSize > payloadSize - dataOffset)
        return FALSE;

    memset(native, 0, sizeof(*native));

    native->H = h;
    native->W = w;
    native->pixelFmt = (GXTexFmt)pixelFmt;
    native->mapingType = (GXOBJVRamModeChar)mapping;
    native->characterFmt = characterFmt;
    native->szByte = dataSize;
    native->pRawData = (void *)(p + dataOffset);

    return TRUE;
}
#endif

static struct CharResExtraData *GetResourceExtraCharData(
    void *resource, int vram, enum HeapID heapID)
{
#ifdef SDK_64BIT
    HGNativeCharResExtra *ret;

    ret = Heap_Alloc(heapID, sizeof(*ret));
    if (!ret)
        return NULL;

    memset(ret, 0, sizeof(*ret));

    if (!HGDecodeNativeCharacter(resource, &ret->native)) {
        Heap_Free(ret);
        GF_ASSERT(FALSE);
        return NULL;
    }

    ret->base.charData = &ret->native;
    ret->base.vram = (NNS_G2D_VRAM_TYPE)vram;

    return &ret->base;
#else
    struct CharResExtraData *ret =
        Heap_Alloc(heapID, sizeof(struct CharResExtraData));

    NNS_G2dGetUnpackedCharacterData(resource, &ret->charData);
    ret->vram = (NNS_G2D_VRAM_TYPE)vram;
    return ret;
#endif
}



#ifdef SDK_64BIT
/*
 * Native NCLR sprite-palette resource adapter.
 *
 * Original Nintendo DS PLTT payload:
 * +0  u32 fmt
 * +4  u32 extended palette flag
 * +8  u32 raw data size
 * +12 u32 raw data offset
 *
 * The native palette structure lives inside its existing
 * resource-extra allocation. The original resource manager
 * owns the raw data and outlives the extra-data structure.
 */
typedef struct HGNativePlttResExtra {
    struct PlttResExtraData base;
    NNSG2dPaletteData native;
} HGNativePlttResExtra;

_Static_assert(
    offsetof(HGNativePlttResExtra, base) == 0,
    "native palette extra-data prefix"
);

static u32 HGPlttRead32(const u8 *p) {
    return (u32)p[0]
        | ((u32)p[1] << 8)
        | ((u32)p[2] << 16)
        | ((u32)p[3] << 24);
}

static BOOL HGDecodeNativePalette(
    void *resource,
    NNSG2dPaletteData *native)
{
    u8 *block;
    const u8 *p;
    u32 blockSize;
    u32 payloadSize;
    u32 fmt;
    u32 extended;
    u32 rawSize;
    u32 rawOffset;

    if (!resource || !native)
        return FALSE;

    block = NNS_G2dFindBinaryBlock(
        resource, (u32)'PLTT'
    );

    if (!block)
        return FALSE;

    blockSize = HGPlttRead32(block + 4);

    if (blockSize < 24)
        return FALSE;

    p = block + 8;
    payloadSize = blockSize - 8;

    fmt = HGPlttRead32(p);
    extended = HGPlttRead32(p + 4);
    rawSize = HGPlttRead32(p + 8);
    rawOffset = HGPlttRead32(p + 12);

    if (rawOffset < 16 || rawOffset > payloadSize)
        return FALSE;

    if (rawSize > payloadSize - rawOffset)
        return FALSE;

    memset(native, 0, sizeof(*native));

    native->fmt = (GXTexFmt)fmt;
    native->bExtendedPlt = (BOOL)extended;
    native->szByte = rawSize;
    native->pRawData = (void *)(p + rawOffset);

    return TRUE;
}
#endif

