        GF_ASSERT(FALSE);
        return NULL;
    }

    ret->base.plttData = &ret->native;
    ret->base.vram = (NNS_G2D_VRAM_TYPE)vram;
    ret->base.pltt_num = pltt_num;

    return &ret->base;
#else
    struct PlttResExtraData *ret =
        Heap_Alloc(heapID, sizeof(struct PlttResExtraData));

    NNS_G2dGetUnpackedPaletteData(resource, &ret->plttData);
    ret->vram = (NNS_G2D_VRAM_TYPE)vram;
    ret->pltt_num = pltt_num;
    return ret;
#endif
}


#ifdef SDK_64BIT
/*
 * Native NCER adapter for the original DS cell-bank layout.
 *
 * Wire bank: 24 bytes.
 * Wire cell with bounding rectangle: 16 bytes.
 * Native bank: 48 bytes.
 * Native cell with bounding rectangle: 24 bytes.
 *
 * Keep OAM attributes in the original resource allocation.
 * The owning SpriteResource destroys this native view first.
 */
typedef struct HGNativeCellWithBR {
    NNSG2dCellData cell;
    u8 bounds[8];
} HGNativeCellWithBR;

_Static_assert(sizeof(NNSG2dCellDataBank) == 48,
               "native cell-bank ABI");
_Static_assert(sizeof(NNSG2dCellData) == 16,
               "native cell ABI");
_Static_assert(sizeof(HGNativeCellWithBR) == 24,
               "native bounding-cell stride");

static u16 HGCellRead16(const u8 *p) {
    return (u16)p[0] | ((u16)p[1] << 8);
}

static u32 HGCellRead32(const u8 *p) {
    return (u32)p[0] | ((u32)p[1] << 8)
        | ((u32)p[2] << 16) | ((u32)p[3] << 24);
}

static NNSG2dCellDataBank *HGDecodeCellBank(
    void *resource, enum HeapID heapID)
{
    u8 *block;
    const u8 *p;
    u32 blockSize, size, cellsOffset, mapping;
    u32 count, attributes, oamOffset, recordBytes;
    u32 i;
    NNSG2dCellDataBank *bank;
    HGNativeCellWithBR *cells;

    if (!resource)
        return NULL;

    block = NNS_G2dFindBinaryBlock(resource, (u32)'CEBK');
    if (!block)
        return NULL;

    blockSize = HGCellRead32(block + 4);
    if (blockSize < 32)
        return NULL;

    p = block + 8;
    size = blockSize - 8;

    count = HGCellRead16(p);
    attributes = HGCellRead16(p + 2);
    cellsOffset = HGCellRead32(p + 4);
    mapping = HGCellRead32(p + 8);

    /*
     * Do not silently discard VRAM transfer, string-bank,
     * extended attributes, or unknown bank attributes.
     * Those require their own verified native conversions.
     */
    if (HGCellRead32(p + 12) ||
        HGCellRead32(p + 16) ||
        HGCellRead32(p + 20) ||
        attributes != 1 ||
        count == 0 ||
        count > 65535)
        return NULL;

    if (cellsOffset < 24 ||
        cellsOffset > size ||
        count > (size - cellsOffset) / 16)
        return NULL;

    recordBytes = count * 16;
    oamOffset = cellsOffset + recordBytes;

    bank = Heap_Alloc(heapID,
        sizeof(*bank) + count * sizeof(*cells));
    if (!bank)
        return NULL;

    memset(bank, 0,
        sizeof(*bank) + count * sizeof(*cells));

    cells = (HGNativeCellWithBR *)(bank + 1);

    for (i = 0; i < count; ++i) {
        const u8 *wire = p + cellsOffset + i * 16;
        u32 numOam = HGCellRead16(wire);
        u32 relative = HGCellRead32(wire + 4);

        if (relative > size - oamOffset ||
            numOam > (size - oamOffset - relative) / 6) {
            Heap_Free(bank);
            return NULL;
        }

        cells[i].cell.numOAMAttrs = (u16)numOam;
        cells[i].cell.cellAttr = HGCellRead16(wire + 2);
        cells[i].cell.pOamAttrArray =
            (NNSG2dCellOAMAttrData *)
            (p + oamOffset + relative);

        memcpy(cells[i].bounds, wire + 8, 8);
    }

    bank->numCells = (u16)count;
    bank->cellBankAttr = (u16)attributes;
    bank->pCellDataArrayHead = (NNSG2dCellData *)cells;
    bank->mappingMode = (NNSG2dCharacterDataMapingType)mapping;

    return bank;
}
#endif

